WITH lines AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, v) SELECT level, DATE_TRUNC('HOUR', log_ts) AS hour_window, host, CORR(status_code, latency_ms) AS corr_status_code_latency_ms, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min FROM lines GROUP BY level, hour_window, host ORDER BY hour_window DESC
